// TestRequestLoadsExactlyOneGeneration verifies authorization and routing cannot mix two runtime views.
func TestRequestLoadsExactlyOneGeneration(t *testing.T) {
	store := cache.New(time.Now)
	store.Register("only-current", "nut", time.Minute)
	digest := sha256.Sum256([]byte("current-token-value"))
	calls := 0
	handler := New(func() View {
		calls++
		if calls == 1 {
			return View{Store: store, TokenDigests: [][sha256.Size]byte{digest}, AllowedClients: []netip.Prefix{netip.MustParsePrefix("192.0.2.0/24")}}
		}
		return View{}
	}, Options{})

	response := httptest.NewRecorder()
	handler.ServeHTTP(response, request(http.MethodGet, "/api/v1/sources", "Bearer current-token-value"))
	if response.Code != http.StatusOK || calls != 1 {
		t.Fatalf("status=%d provider calls=%d", response.Code, calls)
	}
}

type sseFrame struct {
	ID      string
	Event   string
	Data    string
	Comment string
}

type deadlineRecordingWriter struct {
	header    http.Header
	deadlines []time.Time
}

func (w *deadlineRecordingWriter) Header() http.Header {
	if w.header == nil {
		w.header = make(http.Header)
	}
	return w.header
}

func (*deadlineRecordingWriter) WriteHeader(int)                {}
func (*deadlineRecordingWriter) Write(body []byte) (int, error) { return len(body), nil }
func (*deadlineRecordingWriter) Flush()                         {}
func (w *deadlineRecordingWriter) SetWriteDeadline(deadline time.Time) error {
	w.deadlines = append(w.deadlines, deadline)
	return nil
}

func TestSSEWriteClearsPerWriteDeadlineAfterFlush(t *testing.T) {
	writer := &deadlineRecordingWriter{}
	controller := http.NewResponseController(writer)
	if err := writeStatusEvent(writer, controller, statusmodel.Snapshot{}); err != nil {
		t.Fatal(err)
	}
	if len(writer.deadlines) != 2 {
		t.Fatalf("write deadlines=%v, want bounded deadline followed by clear", writer.deadlines)
	}
	if writer.deadlines[0].IsZero() || !writer.deadlines[1].IsZero() {
		t.Fatalf("write deadlines=%v, want non-zero then zero", writer.deadlines)
	}
}

func readSSEFrame(reader *bufio.Reader) (sseFrame, error) {
	var frame sseFrame
	for {
		line, err := reader.ReadString('\n')
		if err != nil {
			return frame, err
		}
		line = strings.TrimSuffix(strings.TrimSuffix(line, "\n"), "\r")
		if line == "" {
			return frame, nil
		}
		if strings.HasPrefix(line, ":") {
			frame.Comment = strings.TrimSpace(strings.TrimPrefix(line, ":"))
			continue
		}
		key, value, found := strings.Cut(line, ":")
		if !found {
			continue
		}
		value = strings.TrimPrefix(value, " ")
		switch key {
		case "id":
			frame.ID = value
		case "event":
			frame.Event = value
		case "data":
			frame.Data = value
		}
	}
}

